def iter_tlog(path: Path) -> Iterator[tuple[int, str, object]]:
    mlog = mavutil.mavlink_connection(str(path), robust_parsing=True)
    while True:
        msg = mlog.recv_match(blocking=False)
        if msg is None:
            return
        if msg.get_type() == "BAD_DATA":
            continue
        timestamp = getattr(msg, "_timestamp", None)
        if timestamp is None:
            timestamp_us = 0
        else:
            timestamp_us = int(timestamp * 1_000_000)
        yield timestamp_us, msg.get_type(), msg


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("tlog", type=Path, help="Input .tlog file")
    parser.add_argument(
        "--target",
        default="auto",
        help=("MAVLink replay endpoint. Use auto to listen on this node's AP_EXPENV_EVM_<node>_XE1 address."),
    )
    parser.add_argument("--baud", type=int, default=115200, help="Serial baud rate")
    parser.add_argument("--speed", type=float, default=1.0, help="Replay speed multiplier")
    parser.add_argument("--no-delay", action="store_true", help="Send packets as fast as possible")
    parser.add_argument(
        "--preserve-log-time",
        action="store_true",
        help="Replay timestamp fields exactly as recorded instead of using current live time",
    )
    parser.add_argument(
        "--include-non-vehicle-packets",
        action="store_true",
        help="Also send packets that appear to originate from GCS/system ids >= 250",
    )
    parser.add_argument(
        "--telemetry-rate",
        type=float,
        default=10.0,
        help=(
            "Cap high-rate telemetry (position/attitude/etc.) to this many Hz "
            "per message type before sending, mimicking how an autopilot "
            "throttles its stream to the rate CHEM requests. Use 0 to disable "
            "and replay at the recorded rate."
        ),
    )
    parser.add_argument("--loop", action="store_true", help="Replay forever")
    parser.add_argument("--max-messages", type=int, default=0, help="Stop after this many packets")
    parser.add_argument("--dry-run", action="store_true", help="Parse timing without sending packets")
    parser.add_argument(
        "--no-wait",
        action="store_true",
        help="Do not pause for a start key when running interactively",
    )
    parser.add_argument(
        "--arm-before-start",
        action="store_true",
        help="Inject an armed vehicle HEARTBEAT before replay starts",
    )
    parser.add_argument(
        "--use-log-arm-state",
        action="store_true",
        help="Replay recorded HEARTBEAT packets unchanged instead of mirroring watched arm state",
    )
    parser.add_argument(
        "--preroll-packets",
        type=int,
        default=80,
        help=(
            "Telemetry packets from the start of the log to resend while waiting; "
            "MAVSDK startup context is also included and does not count against this limit"
        ),
    )
    parser.add_argument(
        "--preroll-period",
        type=float,
        default=1.0,
        help="Seconds between preroll bursts while waiting for Space",
    )
    parser.add_argument("--system-id", type=int, default=1, help="Emulated vehicle system id")
    parser.add_argument("--component-id", type=int, default=1, help="Emulated vehicle component id")
    parser.add_argument(
        "--skip-uhd-conf-update",
        action="store_true",
        help=f"Do not update {UHD_CONF_PATH} with this node's E-VM vehicle address",
    )
    parser.add_argument(
        "--uhd-conf-path",
        type=Path,
        default=UHD_CONF_PATH,
        help="UHD config path to backup and update with this node's E-VM vehicle address",
    )
    parser.add_argument(
        "--chem-vehicle-port",
        type=int,
        default=UHD_VEHICLE_PORT,
        help=("E-VM UDP port exposed to CHEM for the replay vehicle. Defaults away from 14550 so the real vehicle stream can be used for arm state."),
    )
    parser.add_argument(
        "--oeo-agent-id",
        default=os.environ.get("FAKE_AGENT_ID", DEFAULT_OEO_AGENT_ID),
        help="Agent id used for OEO Console display topics",
    )
    parser.add_argument(
        "--oeo-interval",
        type=float,
        default=1.0,
        help="Seconds between OEO Console display updates (0 publishes every progress update)",
    )
    parser.add_argument(
        "--no-oeo",
        action="store_true",
        help="Disable OEO Console display publishing",
    )
    parser.add_argument(
        "--vehicle-log-output",
        type=Path,
        default=default_vehicle_log_output(),
        help=(
            "CSV output for replayed vehicle state. Defaults to "
            "$REPLAY_VEHICLE_LOG_OUTPUT, or "
            "$RESULTS_DIR/${LOG_PREFIX}_replay_vehicleOut.txt when RESULTS_DIR and LOG_PREFIX are set."
        ),
    )
    parser.add_argument(
        "--vehicle-log-rate",
        type=float,
        default=DEFAULT_VEHICLE_LOG_RATE,
        help="Replay vehicle state log sample rate in Hz",
    )
    parser.add_argument(
        "--no-vehicle-log",
        action="store_true",
        help="Disable stdout/file vehicle state logging",
    )
    parser.add_argument(
        "--arm-source",
        default=os.environ.get("REPLAY_ARM_SOURCE", "udpin:0.0.0.0:14550"),
        help="MAVLink source used to watch real/emulated vehicle arm state",
    )
    parser.add_argument(
        "--arm-system-id",
        type=int,
        default=None,
        help="MAVLink system id to watch for arm state; defaults to this node id",
    )
    parser.add_argument(
        "--no-start-on-arm",
        action="store_false",
        default=True,
        dest="start_on_arm",
        help="Do not wait for real/emulated vehicle arm state before replay",
    )
    parser.add_argument(
        "--progress-log-interval",
        type=float,
        default=15.0,
        help="Seconds between OEO info logs about replay progress",
    )
    args = parser.parse_args()
    if args.arm_system_id is None:
        node_id = os.environ.get("AP_EXPENV_THIS_CONTAINER_EXP_NODE_NUM")
        args.arm_system_id = int(node_id) if node_id and node_id.isdigit() else args.system_id
    return args


def default_vehicle_log_output() -> Path | None:
    replay_output = os.environ.get("REPLAY_VEHICLE_LOG_OUTPUT")
    if replay_output:
        return Path(replay_output)

    results_dir = os.environ.get("RESULTS_DIR")
    log_prefix = os.environ.get("LOG_PREFIX")
    if not results_dir or not log_prefix:
        return None
    return Path(results_dir) / f"{log_prefix}_replay_vehicleOut.txt"


def parse_host_env(env_name: str) -> str:
    env_value = os.environ.get(env_name)
    if env_value is None:
        raise ValueError(f"{env_name} is not set")

    value = env_value.strip()
    if not value:
        raise ValueError(f"{env_name} is empty")

    parsed = urlparse(value if "://" in value else f"//{value}")
    host = parsed.hostname
    if host is None:
        host = value.split("/", 1)[0].rsplit(":", 1)[0].strip("[]")
    if not host:
        raise ValueError(f"could not parse a host from {env_name}={env_value!r}")
    return host


def resolve_vehicle_address(port: int = UHD_VEHICLE_PORT) -> str:
    host = resolve_evm_vehicle_host()
    return f"udp://{host}:{port}"


def resolve_evm_vehicle_host() -> str:
    node_id = os.environ.get("AP_EXPENV_THIS_CONTAINER_EXP_NODE_NUM")
    if not node_id:
        raise ValueError("AP_EXPENV_THIS_CONTAINER_EXP_NODE_NUM is not set")

    evm_env = EVM_XE1_ENV_TEMPLATE.format(node_id=node_id)
    return parse_host_env(evm_env)


def resolve_replay_target(target: str, port: int = UHD_VEHICLE_PORT) -> str:
    if target != "auto":
        return target
    return f"udpin:{resolve_evm_vehicle_host()}:{port}"


def uhd_backup_path(conf_path: Path = UHD_CONF_PATH) -> Path:
    return conf_path.with_name(f"{conf_path.name}{UHD_BACKUP_SUFFIX}")


def is_replay_generated_uhd_conf(conf_path: Path = UHD_CONF_PATH) -> bool:
    try:
        return conf_path.read_text(encoding="utf-8").startswith(UHD_GENERATED_MARKER)
    except OSError:
        return False


def backup_uhd_conf(conf_path: Path = UHD_CONF_PATH) -> Path | None:
    replay_backup_path = uhd_backup_path(conf_path)
    if not conf_path.exists():
        return replay_backup_path if replay_backup_path.exists() else None

    if is_replay_generated_uhd_conf(conf_path):
        return replay_backup_path if replay_backup_path.exists() else None

    shutil.copy2(conf_path, replay_backup_path)
    return replay_backup_path


def build_uhd_conf(vehicle_address: str) -> str:
    return f"""{UHD_GENERATED_MARKER}
chem_address: ENV
logical_node: ENV
vusrps:
  - name: ENV
    name_suffix: b205
    usrp_type: b205mini
    serial: AERPAW-B205-01
    vehicle:
      address: "{vehicle_address}"

  - name: ENV
    name_suffix: b210
    usrp_type: b210
    serial: AERPAW-B210-01
    vehicle:
      address: "{vehicle_address}"
"""


def update_uhd_conf_from_environment(
    conf_path: Path = UHD_CONF_PATH,
    vehicle_port: int = UHD_VEHICLE_PORT,
) -> Path | None:
    vehicle_address = resolve_vehicle_address(vehicle_port)
    backup_path = backup_uhd_conf(conf_path)
    conf_path.parent.mkdir(parents=True, exist_ok=True)
    conf_path.write_text(build_uhd_conf(vehicle_address), encoding="utf-8")
    return backup_path


def restore_uhd_conf(conf_path: Path, backup_path: Path | None, updated: bool) -> None:
    if not updated:
        return

    try:
        if backup_path is None:
            if conf_path.exists():
                conf_path.unlink()
            print(f"Removed generated UHD config {conf_path}")
            return

        os.replace(backup_path, conf_path)
        print(f"Restored UHD config from {backup_path}")
    except OSError as exc:
        print(f"Could not restore UHD config: {exc}", file=sys.stderr)


def count_tlog_packets(path: Path, max_messages: int = 0) -> int:
    count = 0
    for _ in iter_tlog(path):
        count += 1
        if max_messages and count >= max_messages:
            break
    return count


def build_progress_text(done: int, total: int) -> str:
    if total <= 0:
        return f"{done} packets"
    done = min(done, total)
    return f"{done / total * 100:.1f}% ({done}/{total})"


def clean_param_id(value: object) -> str:
    if isinstance(value, bytes):
        return value.split(b"\x00", 1)[0].decode("ascii", errors="ignore")
    return str(value).split("\x00", 1)[0]


def now_unix_us() -> int:
    return int(time.time() * 1_000_000)


class ReplayVehicleLogger:
    def __init__(self, enabled: bool, output_path: Path | None, sample_rate: float):
        self.enabled = enabled and sample_rate > 0
        self.output_path = output_path
        self.sample_interval_us = int(1_000_000 / sample_rate) if sample_rate > 0 else 0
        self.next_sample_us: int | None = None
        self.line_num = 1
        self.file = None
        self.writer = None
        self.lat: float | int | None = None
        self.lon: float | int | None = None
        self.alt: float | int | None = None
        self.voltage: float | None = None
        self.fix_type: int | None = None
        self.satellites: int | None = None
        self.attitude = (0.0, 0.0, 0.0)
        self.velocity = (0.0, 0.0, 0.0)

    def __enter__(self) -> ReplayVehicleLogger:
        if self.enabled and self.output_path is not None:
            self.output_path.parent.mkdir(parents=True, exist_ok=True)
            self.file = self.output_path.open("w", newline="", encoding="utf-8")
            self.writer = csv.writer(self.file)
            print(f"Writing replay vehicle state log to {self.output_path}")
        return self

    def __exit__(self, exc_type, exc, tb) -> None:
        if self.file is not None:
            self.file.close()

    def observe(self, timestamp_us: int, mtype: str, msg: object) -> None:
        if not self.enabled:
            return

        self.update_state(mtype, msg)
        if self.next_sample_us is None:
            self.next_sample_us = timestamp_us
        if timestamp_us < self.next_sample_us:
            return
        self.next_sample_us = timestamp_us + self.sample_interval_us
        self.write_sample()

    def update_state(self, mtype: str, msg: object) -> None:
        if mtype == "GLOBAL_POSITION_INT":
            self.lat = getattr(msg, "lat", 0) / 1e7
            self.lon = getattr(msg, "lon", 0) / 1e7
            self.alt = round(getattr(msg, "relative_alt", getattr(msg, "alt", 0)) / 1000.0, 3)
            self.velocity = (
                getattr(msg, "vx", 0) / 100.0,
                getattr(msg, "vy", 0) / 100.0,
                getattr(msg, "vz", 0) / 100.0,
            )
        elif mtype == "GPS_RAW_INT":
            self.fix_type = int(getattr(msg, "fix_type", 0))
            self.satellites = int(getattr(msg, "satellites_visible", 0))
            if self.lat is None and getattr(msg, "lat", 0):
                self.lat = getattr(msg, "lat", 0) / 1e7
                self.lon = getattr(msg, "lon", 0) / 1e7
                self.alt = round(getattr(msg, "alt", 0) / 1000.0, 3)
        elif mtype == "BATTERY_STATUS":
            voltages = list(getattr(msg, "voltages", []) or [])
            valid_voltages = [value for value in voltages if 0 < value < 65535]
            if valid_voltages:
                self.voltage = round(sum(valid_voltages) / 1000.0, 3)
        elif mtype == "SYS_STATUS":
            voltage_battery = getattr(msg, "voltage_battery", 0)
            if voltage_battery > 0:
                self.voltage = round(voltage_battery / 1000.0, 3)
        elif mtype == "ATTITUDE":
            self.attitude = (
                getattr(msg, "pitch", 0.0),
                getattr(msg, "yaw", 0.0),
                getattr(msg, "roll", 0.0),
            )
        elif mtype == "LOCAL_POSITION_NED":
            self.velocity = (
                getattr(msg, "vx", 0.0),
                getattr(msg, "vy", 0.0),
                getattr(msg, "vz", 0.0),
            )
        elif mtype == "VFR_HUD":
            self.velocity = (
                getattr(msg, "groundspeed", 0.0),
                0.0,
                getattr(msg, "climb", 0.0),
            )

    def write_sample(self) -> None:
        lat = self.lat
        lon = self.lon
        alt = self.alt
        fix = self.fix_type if self.fix_type is not None else 0
        satellites = self.satellites if self.satellites is not None else 0
        if fix < 2:
            lat, lon, alt = -999, -999, -999

        timestamp = datetime.datetime.now()
        attitude = "(" + ",".join(str(value) for value in self.attitude) + ")"
        velocity = "(" + ",".join(str(value) for value in self.velocity) + ")"
        voltage = self.voltage if self.voltage is not None else 0.0
        row = [
            self.line_num,
            lon if lon is not None else -999,
            lat if lat is not None else -999,
            alt if alt is not None else -999,
            attitude,
            velocity,
            voltage,
            timestamp,
            fix,
            satellites,
        ]

        if self.writer is not None:
            self.writer.writerow(row)
            self.file.flush()
            os.fsync(self.file.fileno())

        print(
            f"{timestamp}: [DEBUG] {self.line_num}, {row[2]}, {row[1]}, {row[3]}, "
            f"{attitude}, {velocity}, {voltage}, {timestamp}, {fix}, {satellites}"
        )
        self.line_num += 1


class LiveMavlinkAdapter:
    def __init__(self, args: argparse.Namespace):
        self.args = args
        self.mav = mavlink.MAVLink(
            None,
            srcSystem=args.system_id,
            srcComponent=args.component_id,
        )
        self.boot_start = time.monotonic()

    def boot_ms(self) -> int:
        return int((time.monotonic() - self.boot_start) * 1000.0) & 0xFFFFFFFF

    def boot_us(self) -> int:
        return int((time.monotonic() - self.boot_start) * 1_000_000.0)

    def normalize_replayed_message(self, msg: object) -> None:
        if self.args.preserve_log_time:
            return

        mtype = msg.get_type()
        unix_us = now_unix_us()
        boot_ms = self.boot_ms()

        if mtype in BOOT_TIME_MS_FIELDS and hasattr(msg, "time_boot_ms"):
            msg.time_boot_ms = boot_ms
        if mtype in UNIX_TIME_US_FIELDS and hasattr(msg, "time_usec"):
            msg.time_usec = unix_us
        if mtype in BOOT_TIME_US_FIELDS and hasattr(msg, "time_usec"):
            msg.time_usec = self.boot_us()
        if mtype == "SYSTEM_TIME":
            msg.time_unix_usec = unix_us
            msg.time_boot_ms = boot_ms
        elif mtype == "TIMESYNC":
            msg.tc1 = unix_us if msg.tc1 else 0
            msg.ts1 = unix_us

    def pack_replayed(self, msg: object) -> bytes:
        if self.args.preserve_log_time:
            return msg.get_msgbuf()

        self.normalize_replayed_message(msg)
        self.mav.srcSystem = self.args.system_id
        self.mav.srcComponent = self.args.component_id
        original = msg.get_msgbuf()
        force_mavlink1 = bool(original and original[0] == 0xFE)
        return msg.pack(self.mav, force_mavlink1=force_mavlink1)

    def pack_generated(self, msg: object) -> bytes:
        self.mav.srcSystem = self.args.system_id
        self.mav.srcComponent = self.args.component_id
        return msg.pack(self.mav)

    def heartbeat(self, armed: bool) -> bytes:
        base_mode = mavlink.MAV_MODE_FLAG_CUSTOM_MODE_ENABLED
        if armed:
            base_mode |= mavlink.MAV_MODE_FLAG_SAFETY_ARMED
        msg = self.mav.heartbeat_encode(
            mavlink.MAV_TYPE_GROUND_ROVER,
            mavlink.MAV_AUTOPILOT_ARDUPILOTMEGA,
            base_mode,
            0,
            mavlink.MAV_STATE_ACTIVE if armed else mavlink.MAV_STATE_STANDBY,
        )
        return self.pack_generated(msg)

    def system_time(self) -> bytes:
        msg = self.mav.system_time_encode(now_unix_us(), self.boot_ms())
        return self.pack_generated(msg)

    def timesync_response(self, request_msg: object) -> bytes:
        msg = self.mav.timesync_encode(
            getattr(request_msg, "ts1", 0),
            now_unix_us(),
        )
        return self.pack_generated(msg)

    def command_ack(self, command_msg: object, result: int = mavlink.MAV_RESULT_ACCEPTED) -> bytes:
        msg = self.mav.command_ack_encode(
            command_msg.command,
            result,
            0,
            0,
            command_msg.get_srcSystem(),
            command_msg.get_srcComponent(),
        )
        return self.pack_generated(msg)


class StartupContext:
    def __init__(self, args: argparse.Namespace):
        self.args = args
        self.params: dict[str, object] = {}
        self.param_order: list[str] = []
        self.autopilot_version: object | None = None
        self.home_position: object | None = None

    def update(self, msg: object) -> None:
        mtype = msg.get_type()
        if mtype == "PARAM_VALUE":
            name = clean_param_id(getattr(msg, "param_id", ""))
            if name:
                if name not in self.params:
                    self.param_order.append(name)
                self.params[name] = msg
        elif mtype == "AUTOPILOT_VERSION":
            self.autopilot_version = msg
        elif mtype == "HOME_POSITION":
            self.home_position = msg

    def send_all_params(self, connection: object, adapter: LiveMavlinkAdapter) -> None:
        count = len(self.param_order)
        for index, name in enumerate(self.param_order):
            msg = self.params[name]
            msg.param_count = count
            msg.param_index = index
            connection.write(adapter.pack_replayed(msg))

    def send_param(
        self,
        connection: object,
        adapter: LiveMavlinkAdapter,
        param_id: str | None = None,
        param_index: int | None = None,
    ) -> bool:
        if param_id:
            msg = self.params.get(param_id)
        elif param_index is not None and 0 <= param_index < len(self.param_order):
            msg = self.params[self.param_order[param_index]]
        else:
            msg = None
        if msg is None:
            return False
        msg.param_count = len(self.param_order)
        msg.param_index = self.param_order.index(clean_param_id(msg.param_id))
        connection.write(adapter.pack_replayed(msg))
        return True

    def send_message_id(
        self,
        connection: object,
        adapter: LiveMavlinkAdapter,
        message_id: int,
    ) -> bool:
        if (
            message_id == mavlink.MAVLINK_MSG_ID_AUTOPILOT_VERSION
            and self.autopilot_version is not None
        ):
            connection.write(adapter.pack_replayed(self.autopilot_version))
            return True
        if (
            message_id == mavlink.MAVLINK_MSG_ID_HOME_POSITION
            and self.home_position is not None
        ):
            connection.write(adapter.pack_replayed(self.home_position))
            return True
        if message_id == mavlink.MAVLINK_MSG_ID_SYSTEM_TIME:
            connection.write(adapter.system_time())
            return True
        return False


class ArmStateMonitor:
    def __init__(self, source: str, system_id: int):
        self.source = source
        self.system_id = system_id
        self.connection = mavutil.mavlink_connection(source, robust_parsing=True)
        self.last_armed: bool | None = None

    def poll(self) -> bool | None:
        while True:
            msg = self.connection.recv_match(type="HEARTBEAT", blocking=False)
            if msg is None:
                return self.last_armed
            if msg.get_srcSystem() != self.system_id:
                continue
            self.last_armed = bool(msg.base_mode & mavlink.MAV_MODE_FLAG_SAFETY_ARMED)


class OEOReplayPublisher:
    def __init__(self, agent_id: str, enabled: bool, interval: float):
        self.agent_id = str(agent_id)
        self.enabled = enabled
        self.interval = max(0.0, interval)
        self.next_publish = 0.0
        self.platform = None

        if not self.enabled:
            return

        try:
            from aerpawlib.aerpaw import AERPAW_Platform
        except ImportError:
            self.enabled = False
            print("aerpawlib is not available; OEO display publishing disabled")
            return

        self.platform = AERPAW_Platform

    def print_console_setup(self) -> None:
        print("")
        print("OEO Console setup for replay display:")
        for field in OEO_DISPLAY_FIELDS:
            print(f"  add {field}")
        print("")
        print("Optional shorter labels:")
        print("  remap user/vehicle/status replay_armed")
        print("  remap user/vehicle/mode replay_mode")
        print("  remap user/vehicle/replay/progress replay_progress")
        print("")
        print("Replay starts when the watched MAVLink vehicle reports armed. Use q in this replay terminal to quit while waiting.")
        print("")

    def log(self, message: str) -> None:
        if self.enabled and self.platform is not None:
            self.platform.log_to_oeo(message, "INFO", agent_id=self.agent_id)

    def publish_field(self, topic: str, value: object) -> None:
        if self.enabled and self.platform is not None and value is not None:
            self.platform.publish_user_oeo_topic(str(value), topic, agent_id=self.agent_id)

    def publish_status(
        self,
        armed: bool,
        mode: str,
        progress: str | None = None,
        force: bool = False,
    ) -> None:
        if not self.enabled:
            return

        now = time.monotonic()
        if not force and self.interval > 0 and now < self.next_publish:
            return
        self.next_publish = now + self.interval

        self.publish_field("vehicle/status", 1 if armed else 0)
        self.publish_field("vehicle/mode", mode)
        self.publish_field("vehicle/replay/progress", progress)


def send_heartbeat(
    connection: object,
    armed: bool,
    adapter: LiveMavlinkAdapter,
) -> None:
    connection.write(adapter.heartbeat(armed))
    state = "armed" if armed else "disarmed"
    print(f"Injected {state} vehicle heartbeat")


class Keyboard:
    def __init__(self, enabled: bool):
        self.enabled = enabled
        self.fd: int | None = None
        self.old_settings = None

    def __enter__(self) -> Keyboard:
        if self.enabled:
            self.fd = sys.stdin.fileno()
            self.old_settings = termios.tcgetattr(self.fd)
            tty.setcbreak(self.fd)
        return self

    def __exit__(self, exc_type, exc, tb) -> None:
        if self.enabled and self.fd is not None and self.old_settings is not None:
            termios.tcsetattr(self.fd, termios.TCSADRAIN, self.old_settings)

    def read(self, timeout: float = 0.0) -> str | None:
        if not self.enabled:
            return None
        readable, _, _ = select.select([sys.stdin], [], [], timeout)
        if not readable:
            return None
        return sys.stdin.read(1)


def load_preroll_packets(args: argparse.Namespace) -> tuple[list[object], StartupContext]:
    context = StartupContext(args)
    if args.preroll_packets <= 0:
        return [], context
    packets: list[object] = []
    telemetry_packets = 0
    mlog = mavutil.mavlink_connection(str(args.tlog), robust_parsing=True)
    while True:
        msg = mlog.recv_match(blocking=False)
        if msg is None:
            break
        mtype = msg.get_type()
        if not args.include_non_vehicle_packets and msg.get_srcSystem() >= GCS_SOURCE_SYSTEM_MIN:
            continue
        context.update(msg)
        if mtype in PREROLL_CONTEXT_TYPES:
            packets.append(msg)
            continue
        if mtype not in PREROLL_TELEMETRY_TYPES:
            continue
        packets.append(msg)
        telemetry_packets += 1
        if telemetry_packets >= args.preroll_packets:
            break
    return packets, context


def send_preroll(
    connection: object | None,
    packets: list[object],
    armed: bool,
    args: argparse.Namespace,
    adapter: LiveMavlinkAdapter,
    context: StartupContext,
) -> None:
    if connection is None:
        return
    respond_to_commands(connection, args, adapter, context)
    connection.write(adapter.heartbeat(armed))
    for msg in packets:
        connection.write(adapter.pack_replayed(msg))


def respond_to_commands(
    connection: object | None,
    args: argparse.Namespace,
    adapter: LiveMavlinkAdapter,
    context: StartupContext,
) -> None:
    if connection is None:
        return
    while True:
        try:
            msg = connection.recv_match(blocking=False)
        except Exception:
            return
        if msg is None:
            return
        mtype = msg.get_type()
        if mtype == "TIMESYNC":
            connection.write(adapter.timesync_response(msg))
        elif mtype == "PARAM_REQUEST_LIST":
            context.send_all_params(connection, adapter)
        elif mtype == "PARAM_REQUEST_READ":
            param_id = clean_param_id(getattr(msg, "param_id", ""))
            param_index = int(getattr(msg, "param_index", -1))
            context.send_param(
                connection,
                adapter,
                param_id=param_id or None,
                param_index=param_index if param_index >= 0 else None,
            )
        elif mtype in ("COMMAND_LONG", "COMMAND_INT"):
            handled = False
            command = int(getattr(msg, "command", 0))
            if command == mavlink.MAV_CMD_REQUEST_MESSAGE:
                message_id = int(getattr(msg, "param1", 0))
                handled = context.send_message_id(connection, adapter, message_id)
            elif command == mavlink.MAV_CMD_SET_MESSAGE_INTERVAL:
                handled = True
            connection.write(
                adapter.command_ack(
                    msg,
                    mavlink.MAV_RESULT_ACCEPTED if handled else mavlink.MAV_RESULT_UNSUPPORTED,
                )
            )


def handle_control_key(key: str, armed: bool) -> tuple[bool, bool, bool]:
    """Return (continue_running, paused, armed)."""
    if key.lower() == "q":
        print("Replay cancelled")
        return False, False, armed
    if key == "p":
        print("Replay paused. Space resumes, q quits.")
        return True, True, armed
    return True, False, armed


def wait_for_start(
    args: argparse.Namespace,
    connection: object | None,
    keyboard: Keyboard,
    preroll_packets: list[object],
    adapter: LiveMavlinkAdapter,
    context: StartupContext,
    armed: bool,
    oeo: OEOReplayPublisher,
    arm_monitor: ArmStateMonitor | None,
    progress: str,
) -> tuple[bool, bool]:
    if args.dry_run or args.no_wait:
        oeo.publish_status(armed, "REPLAYING", progress=progress, force=True)
        return True, armed

    if args.start_on_arm and arm_monitor is not None:
        print("Replay ready.")
        print(f"Watching {args.arm_source} for armed HEARTBEAT from MAVLink system id {args.arm_system_id}.")
        print("Replay starts automatically when the watched vehicle arms.")
        print("  q: quit")
        oeo.publish_status(False, "WAITING_ARM", progress=progress, force=True)

        next_preroll = 0.0
        last_reported_armed: bool | None = None
        while True:
            now = time.monotonic()
            if args.preroll_period > 0 and now >= next_preroll:
                send_preroll(connection, preroll_packets, False, args, adapter, context)
                next_preroll = now + args.preroll_period

            source_armed = arm_monitor.poll()
            if source_armed is not None and source_armed != last_reported_armed:
                last_reported_armed = source_armed
                state = "armed" if source_armed else "disarmed"
                print(f"Watched vehicle is {state}")
                oeo.publish_status(source_armed, "WAITING_ARM", progress=progress, force=True)
            if source_armed:
                armed = True
                if connection is not None:
                    send_heartbeat(connection, True, adapter)
                print("Watched vehicle armed; starting replay")
                oeo.log("Watched vehicle armed; starting replay")
                oeo.publish_status(True, "REPLAYING", progress=progress, force=True)
                return True, armed

            key = keyboard.read(0.1)
            if key is not None and key.lower() == "q":
                print("Replay cancelled")
                return False, armed

    if not keyboard.enabled:
        oeo.publish_status(armed, "REPLAYING", progress=progress, force=True)
        return True, armed

    print("Replay ready.")
    print("  Space: start replay")
    print("  q: quit")
    print("Sending heartbeat while waiting...")
    oeo.publish_status(armed, "WAITING", progress=progress, force=True)

    next_preroll = 0.0
    while True:
        now = time.monotonic()
        if args.preroll_period > 0 and now >= next_preroll:
            send_preroll(connection, preroll_packets, armed, args, adapter, context)
            next_preroll = now + args.preroll_period

        key = keyboard.read(0.1)
        if key is None:
            continue
        if key == " ":
            print("Starting replay")
            oeo.publish_status(armed, "REPLAYING", progress=progress, force=True)
            return True, armed
        keep_going, _, armed = handle_control_key(key, armed)
        oeo.publish_status(armed, "WAITING", progress=progress, force=True)
        if not keep_going:
            return False, armed


def wait_while_paused(
    args: argparse.Namespace,
    connection: object | None,
    keyboard: Keyboard,
    preroll_packets: list[object],
    adapter: LiveMavlinkAdapter,
    context: StartupContext,
    armed: bool,
    oeo: OEOReplayPublisher,
    progress: str,
) -> tuple[bool, bool]:
    oeo.publish_status(armed, "PAUSED", progress=progress, force=True)
    next_preroll = 0.0
    while True:
        now = time.monotonic()
        if args.preroll_period > 0 and now >= next_preroll:
            send_preroll(connection, preroll_packets, armed, args, adapter, context)
            next_preroll = now + args.preroll_period
        key = keyboard.read(0.1)
        if key is None:
            continue
        if key == " ":
            print("Replay resumed")
            oeo.publish_status(armed, "REPLAYING", progress=progress, force=True)
            return True, armed
        keep_going, _, armed = handle_control_key(key, armed)
        oeo.publish_status(armed, "PAUSED", progress=progress, force=True)
        if not keep_going:
            return False, armed


def replay_once(
    args: argparse.Namespace,
    connection: object | None,
    keyboard: Keyboard,
    preroll_packets: list[object],
    adapter: LiveMavlinkAdapter,
    context: StartupContext,
    vehicle_logger: ReplayVehicleLogger,
    armed: bool,
    oeo: OEOReplayPublisher,
    arm_monitor: ArmStateMonitor | None,
    total_expected: int,
) -> tuple[int, bool, bool]:
    first_ts: int | None = None
    started = time.monotonic()
    count = 0
    paused_total = 0.0
    rate_interval_us = (
        int(1_000_000 / args.telemetry_rate) if args.telemetry_rate > 0 else 0
    )
    last_sent_us: dict[str, int] = {}
    next_oeo_log = (
        time.monotonic() + args.progress_log_interval
        if args.progress_log_interval > 0
        else None
    )

    progress_iter = iter_tlog(args.tlog)
    progress_bar = tqdm(
        total=total_expected,
        unit="pkt",
        desc="Replay",
        dynamic_ncols=True,
    )

    try:
        for timestamp_us, mtype, msg in progress_iter:
            if first_ts is None:
                first_ts = timestamp_us

            if not args.no_delay:
                desired_elapsed = ((timestamp_us - first_ts) / 1_000_000.0) / args.speed
                sleep_for = started + paused_total + desired_elapsed - time.monotonic()
                if sleep_for > 0:
                    time.sleep(sleep_for)

            respond_to_commands(connection, args, adapter, context)

            source_armed = arm_monitor.poll() if arm_monitor is not None else None
            if source_armed is not None and source_armed != armed:
                armed = source_armed
                if connection is not None:
                    send_heartbeat(connection, armed, adapter)
                state = "armed" if armed else "disarmed"
                print(f"Watched vehicle changed to {state}")

            key = keyboard.read(0.0)
            if key is not None:
                if key == " ":
                    print("Replay paused. Space resumes, q quits.")
                    paused_started = time.monotonic()
                    progress = build_progress_text(count, total_expected)
                    keep_going, armed = wait_while_paused(
                        args,
                        connection,
                        keyboard,
                        preroll_packets,
                        adapter,
                        context,
                        armed,
                        oeo,
                        progress,
                    )
                    paused_total += time.monotonic() - paused_started
                    if not keep_going:
                        return count, False, armed
                else:
                    keep_going, pause_now, armed = handle_control_key(key, armed)
                    oeo.publish_status(
                        armed,
                        "REPLAYING",
                        progress=build_progress_text(count, total_expected),
                        force=True,
                    )
                    if not keep_going:
                        return count, False, armed
                    if pause_now:
                        paused_started = time.monotonic()
                        progress = build_progress_text(count, total_expected)
                        keep_going, armed = wait_while_paused(
                            args,
                            connection,
                            keyboard,
                            preroll_packets,
                            adapter,
                            context,
                            armed,
                            oeo,
                            progress,
                        )
                        paused_total += time.monotonic() - paused_started
                        if not keep_going:
                            return count, False, armed

            send_packet = True
            if mtype == "HEARTBEAT" and not args.use_log_arm_state:
                packet = adapter.heartbeat(armed)
            elif (
                not args.include_non_vehicle_packets
                and msg.get_srcSystem() >= GCS_SOURCE_SYSTEM_MIN
            ):
                send_packet = False
            else:
                packet = adapter.pack_replayed(msg)
                if msg.get_srcSystem() < GCS_SOURCE_SYSTEM_MIN:
                    vehicle_logger.observe(timestamp_us, mtype, msg)

            if rate_interval_us and mtype in RATE_LIMITED_TYPES:
                prev = last_sent_us.get(mtype)
                if prev is not None and (timestamp_us - prev) < rate_interval_us:
                    send_packet = False
                else:
                    last_sent_us[mtype] = timestamp_us

            if send_packet and connection is not None:
                connection.write(packet)

            count += 1
            progress_bar.update(1)

            progress = build_progress_text(count, total_expected)
            oeo.publish_status(
                armed,
                "REPLAYING",
                progress=progress,
            )
            if next_oeo_log is not None and time.monotonic() >= next_oeo_log:
                oeo.log(f"Replay progress {progress}")
                next_oeo_log = time.monotonic() + args.progress_log_interval

            if args.max_messages and count >= args.max_messages:
                break
    finally:
        progress_bar.close()

    return count, True, armed


def main() -> int:
    args = parse_args()
    oeo = OEOReplayPublisher(
        agent_id=args.oeo_agent_id,
        enabled=not args.no_oeo and not args.dry_run,
        interval=args.oeo_interval,
    )
    oeo.print_console_setup()
    if args.speed <= 0:
        print("--speed must be greater than zero", file=sys.stderr)
        return 2
    if args.target.startswith("udpout:0.0.0.0:") or args.target.startswith("udpout://0.0.0.0:"):
        print(
            "--target must not use 0.0.0.0 as a remote udpout destination",
            file=sys.stderr,
        )
        return 2
    if not args.dry_run:
        try:
            args.target = resolve_replay_target(args.target, args.chem_vehicle_port)
        except ValueError as exc:
            print(f"Could not resolve replay target: {exc}", file=sys.stderr)
            return 2
    chem_host = os.environ.get("AP_EXPENV_CHEMVM_XE")
    if chem_host and (args.target.startswith(f"udpout:{chem_host}:") or args.target.startswith(f"udpout://{chem_host}:")):
        print(
            "--target should be the local E-VM vehicle listener, not the CHEM VM. Use --target auto.",
            file=sys.stderr,
        )
        return 2
    if not args.dry_run:
        print(f"Resolved MAVLink replay endpoint: {args.target}")
    total_expected = count_tlog_packets(args.tlog, args.max_messages)
    initial_progress = build_progress_text(0, total_expected)
    print(f"Loaded replay log metadata: {total_expected} packet(s)")

    uhd_backup_path: Path | None = None
    uhd_conf_updated = False
    if not args.dry_run and not args.skip_uhd_conf_update and os.environ.get("AP_EXPENV_THIS_CONTAINER_EXP_NODE_NUM") is not None:
        try:
            uhd_backup_path = update_uhd_conf_from_environment(
                args.uhd_conf_path,
                args.chem_vehicle_port,
            )
            uhd_conf_updated = True
        except (OSError, ValueError) as exc:
            print(f"Could not update UHD config: {exc}", file=sys.stderr)
            return 1
        if uhd_backup_path is None:
            print(f"Wrote UHD config to {args.uhd_conf_path} (no existing config to backup)")
        else:
            print(f"Backed up UHD config to {uhd_backup_path}")
            print(f"Wrote UHD config to {args.uhd_conf_path}")

    total = 0
    loops = 0
    armed = bool(args.arm_before_start)
    adapter = LiveMavlinkAdapter(args)
    startup_context = StartupContext(args)
    vehicle_logger = ReplayVehicleLogger(
        enabled=not args.no_vehicle_log and not args.dry_run,
        output_path=args.vehicle_log_output,
        sample_rate=args.vehicle_log_rate,
    )
    try:
        vehicle_logger.__enter__()
        connection = None
        arm_monitor = None
        preroll_packets: list[object] = []
        if not args.dry_run:
            try:
                arm_monitor = ArmStateMonitor(args.arm_source, args.arm_system_id)
                print(f"Watching {args.arm_source} for arm state from MAVLink system id {args.arm_system_id}")
            except Exception as exc:
                print(f"Could not open arm source {args.arm_source}: {exc}", file=sys.stderr)
                if args.start_on_arm:
                    return 1
            connection = mavutil.mavlink_connection(args.target, baud=args.baud)
            print(f"Replaying {args.tlog} to {args.target} at {args.speed:g}x")
            oeo.log(f"replay vehicle {args.oeo_agent_id} is alive")
            preroll_packets, startup_context = load_preroll_packets(args)
            if preroll_packets:
                print(f"Loaded {len(preroll_packets)} preroll packets for QGC acquisition")
            if args.arm_before_start:
                send_heartbeat(connection, True, adapter)
            oeo.publish_status(armed, "STARTING", progress=initial_progress, force=True)

        try:
            keyboard_enabled = not args.dry_run and not args.no_wait and sys.stdin.isatty()
            with Keyboard(keyboard_enabled) as keyboard:
                should_start, armed = wait_for_start(
                    args,
                    connection,
                    keyboard,
                    preroll_packets,
                    adapter,
                    startup_context,
                    armed,
                    oeo,
                    arm_monitor,
                    initial_progress,
                )
                if not should_start:
                    oeo.publish_status(
                        armed,
                        "CANCELLED",
                        progress=build_progress_text(total, total_expected),
                        force=True,
                    )
                    return 0

                while True:
                    sent, keep_going, armed = replay_once(
                        args,
                        connection,
                        keyboard,
                        preroll_packets,
                        adapter,
                        startup_context,
                        vehicle_logger,
                        armed,
                        oeo,
                        arm_monitor,
                        total_expected,
                    )
                    total += sent
                    loops += 1
                    if not keep_going or not args.loop or sent == 0 or args.max_messages:
                        break
        except KeyboardInterrupt:
            print("\nReplay interrupted", file=sys.stderr)
        action = "Parsed" if args.dry_run else "Sent"
        suffix = f" in {loops} loop(s)" if args.loop else ""
        print(f"{action} {total} MAVLink packets{suffix}")
        oeo.publish_status(
            armed,
            "DONE",
            progress=build_progress_text(total, total_expected),
            force=True,
        )
        return 0
    finally:
        vehicle_logger.__exit__(None, None, None)
        restore_uhd_conf(args.uhd_conf_path, uhd_backup_path, uhd_conf_updated)


if __name__ == "__main__":
    sys.exit(main())
